111 |         const paginatedTransactions = transactions.slice(startIndex, endIndex);
112 |         const total = transactions.length;
113 |         const totalPages = Math.ceil(total / limit);
114 | 
115 |         return {
116 |             transactions: paginatedTransactions,
117 |             total,
118 |             page,
119 |             limit,
120 |             totalPages
121 |         };
