144 |     if (stockIds.length === 0) {
145 |       return [];
146 |     }
147 | 
148 |     const quotes: Quote[] = [];
149 | 
150 |     for (const stockId of stockIds) {
151 |       const quote = await this.quoteRepository.findLatestByIsin(stockId);
152 |       if (quote) {
153 |         quotes.push(this.mapDBQuoteToBFF(quote));
